using BotFramework.Discord.Commands;using BotFramework.Discord.Routing;using Games.Bowling.Application.Services;
namespace Games.Bowling.Discord;
public sealed class BowlingDiscordHandler(IBowlingService service):IDiscordMessageHandler{public bool CanHandle(DiscordMessageContext context)=>DiscordCommand.Is(context,"bowling");public async Task HandleAsync(DiscordMessageContext context){var p=DiscordCommand.Parts(context);if(p.Length!=2||!int.TryParse(p[1], System.Globalization.CultureInfo.InvariantCulture, out var amount)||amount<=0){await DiscordCommand.ReplyAsync(context,"Использование: `bowling <ставка>`");return;}var u=DiscordCommand.UserId(context);var s=DiscordCommand.ScopeId(context);var src=DiscordCommand.SourceId(context);var n=DiscordCommand.DisplayName(context);_ = await service.PlaceBetAsync(u,n,s,amount,src,context.CancellationToken);var face=DiscordCommand.RandomFace(1,6);var r=await service.RollAsync(u,n,s,face,src,context.CancellationToken);await DiscordCommand.ReplyResultAsync(context,r,"Bowling: "+face);}}
